  assign io_down_a_payload_data = io_up_a_haltWhen_throwWhen_payload_data;
  assign io_down_a_payload_corrupt = io_up_a_haltWhen_throwWhen_payload_corrupt;
  assign _zz_io_down_d_ready = (! doIt);
  assign io_down_d_haltWhen_valid = (io_down_d_valid && _zz_io_down_d_ready);
  assign io_down_d_ready = (io_down_d_haltWhen_ready && _zz_io_down_d_ready);
  assign io_down_d_haltWhen_payload_opcode = io_down_d_payload_opcode;
  assign io_down_d_haltWhen_payload_param = io_down_d_payload_param;
  assign io_down_d_haltWhen_payload_source = io_down_d_payload_source;
