  assign io_down_d_haltWhen_payload_corrupt = io_down_d_payload_corrupt;
  always @(*) begin
    io_up_d_valid = io_down_d_haltWhen_valid;
    if(doIt) begin
      io_up_d_valid = 1'b1;
    end
  end

  assign io_down_d_haltWhen_ready = io_up_d_ready;
  always @(*) begin
    io_up_d_payload_opcode = io_down_d_haltWhen_payload_opcode;
    if(doIt) begin
      io_up_d_payload_opcode = _zz_io_up_d_payload_opcode;
    end
  end

  always @(*) begin
    io_up_d_payload_param = io_down_d_haltWhen_payload_param;
    if(doIt) begin
      io_up_d_payload_param = 3'b000;
    end
  end

  always @(*) begin
    io_up_d_payload_source = io_down_d_haltWhen_payload_source;
    if(doIt) begin
      io_up_d_payload_source = source;
    end
  end

  always @(*) begin
    io_up_d_payload_size = io_down_d_haltWhen_payload_size;
    if(doIt) begin
      io_up_d_payload_size = size;
    end
  end

  always @(*) begin
    io_up_d_payload_denied = io_down_d_haltWhen_payload_denied;
    if(doIt) begin
      io_up_d_payload_denied = 1'b1;
    end
  end

  assign io_up_d_payload_data = io_down_d_haltWhen_payload_data;
  always @(*) begin
    io_up_d_payload_corrupt = io_down_d_haltWhen_payload_corrupt;
    if(doIt) begin
      io_up_d_payload_corrupt = 1'b0;
    end
  end

  always @(*) begin
    case(opcode)
      A_PUT_FULL_DATA : begin
        _zz_io_up_d_payload_opcode = D_ACCESS_ACK;
      end
      A_PUT_PARTIAL_DATA : begin
        _zz_io_up_d_payload_opcode = D_ACCESS_ACK;
      end
      A_GET : begin
        _zz_io_up_d_payload_opcode = D_ACCESS_ACK_DATA;
      end
      A_ACQUIRE_BLOCK : begin
        _zz_io_up_d_payload_opcode = D_GRANT_DATA;
      end
      default : begin
        _zz_io_up_d_payload_opcode = D_GRANT;
      end
    endcase
  end

  always @(posedge litex_clk or posedge litex_reset) begin
    if(litex_reset) begin
      io_up_a_tracker_beat <= 4'b0000;
      errored <= 1'b0;
      doIt <= 1'b0;
      io_down_d_tracker_beat <= 4'b0000;
      io_up_d_tracker_beat <= 4'b0000;
    end else begin
      if(io_up_a_fire) begin
        io_up_a_tracker_beat <= (io_up_a_tracker_beat + 4'b0001);
        if(io_up_a_tracker_last) begin
          io_up_a_tracker_beat <= 4'b0000;
        end
      end
      if(start) begin
        errored <= 1'b1;
      end
      if(io_down_d_fire) begin
        io_down_d_tracker_beat <= (io_down_d_tracker_beat + 4'b0001);
        if(io_down_d_tracker_last) begin
          io_down_d_tracker_beat <= 4'b0000;
