        if(io_up_d_tracker_last) begin
          io_up_d_tracker_beat <= 4'b0000;
        end
      end
      if(when_TransferFilter_l74_1) begin
        doIt <= 1'b0;
      end
      if(doIt) begin
        if(io_up_d_ready) begin
          if(io_up_d_tracker_last) begin
            errored <= 1'b0;
          end
        end
      end
    end
  end

  always @(posedge litex_clk) begin
    if(start) begin
      opcode <= io_up_a_payload_opcode;
    end
    if(start) begin
      size <= io_up_a_payload_size;
    end
    if(start) begin
      source <= io_up_a_payload_source;
    end
    if(doIt) begin
      if(io_up_d_ready) begin
