//StreamFork_1 replaced by StreamFork

module StreamFork (
  input  wire          io_input_valid,
  output reg           io_input_ready,
  input  wire [31:0]   io_input_payload_addr,
  input  wire [3:0]    io_input_payload_id,
  input  wire [3:0]    io_input_payload_region,
  input  wire [7:0]    io_input_payload_len,
  input  wire [2:0]    io_input_payload_size,
  input  wire [1:0]    io_input_payload_burst,
  input  wire [0:0]    io_input_payload_lock,
  input  wire [3:0]    io_input_payload_cache,
  input  wire [3:0]    io_input_payload_qos,
  input  wire [2:0]    io_input_payload_prot,
  output wire          io_outputs_0_valid,
  input  wire          io_outputs_0_ready,
  output wire [31:0]   io_outputs_0_payload_addr,
  output wire [3:0]    io_outputs_0_payload_id,
  output wire [3:0]    io_outputs_0_payload_region,
  output wire [7:0]    io_outputs_0_payload_len,
  output wire [2:0]    io_outputs_0_payload_size,
  output wire [1:0]    io_outputs_0_payload_burst,
  output wire [0:0]    io_outputs_0_payload_lock,
  output wire [3:0]    io_outputs_0_payload_cache,
  output wire [3:0]    io_outputs_0_payload_qos,
  output wire [2:0]    io_outputs_0_payload_prot,
  output wire          io_outputs_1_valid,
  input  wire          io_outputs_1_ready,
  output wire [31:0]   io_outputs_1_payload_addr,
  output wire [3:0]    io_outputs_1_payload_id,
  output wire [3:0]    io_outputs_1_payload_region,
  output wire [7:0]    io_outputs_1_payload_len,
  output wire [2:0]    io_outputs_1_payload_size,
  output wire [1:0]    io_outputs_1_payload_burst,
  output wire [0:0]    io_outputs_1_payload_lock,
  output wire [3:0]    io_outputs_1_payload_cache,
  output wire [3:0]    io_outputs_1_payload_qos,
  output wire [2:0]    io_outputs_1_payload_prot,
  input  wire          litex_clk,
  input  wire          litex_reset
);

  reg                 logic_linkEnable_0;
  reg                 logic_linkEnable_1;
  wire                when_Stream_l1355;
  wire                when_Stream_l1355_1;
  wire                io_outputs_0_fire;
  wire                io_outputs_1_fire;

  always @(*) begin
    io_input_ready = 1'b1;
    if(when_Stream_l1355) begin
      io_input_ready = 1'b0;
    end
    if(when_Stream_l1355_1) begin
      io_input_ready = 1'b0;
    end
  end

  assign when_Stream_l1355 = ((! io_outputs_0_ready) && logic_linkEnable_0);
  assign when_Stream_l1355_1 = ((! io_outputs_1_ready) && logic_linkEnable_1);
  assign io_outputs_0_valid = (io_input_valid && logic_linkEnable_0);
  assign io_outputs_0_payload_addr = io_input_payload_addr;
  assign io_outputs_0_payload_id = io_input_payload_id;
  assign io_outputs_0_payload_region = io_input_payload_region;
  assign io_outputs_0_payload_len = io_input_payload_len;
  assign io_outputs_0_payload_size = io_input_payload_size;
  assign io_outputs_0_payload_burst = io_input_payload_burst;
  assign io_outputs_0_payload_lock = io_input_payload_lock;
  assign io_outputs_0_payload_cache = io_input_payload_cache;
  assign io_outputs_0_payload_qos = io_input_payload_qos;
  assign io_outputs_0_payload_prot = io_input_payload_prot;
  assign io_outputs_0_fire = (io_outputs_0_valid && io_outputs_0_ready);
  assign io_outputs_1_valid = (io_input_valid && logic_linkEnable_1);
  assign io_outputs_1_payload_addr = io_input_payload_addr;
  assign io_outputs_1_payload_id = io_input_payload_id;
  assign io_outputs_1_payload_region = io_input_payload_region;
  assign io_outputs_1_payload_len = io_input_payload_len;
  assign io_outputs_1_payload_size = io_input_payload_size;
  assign io_outputs_1_payload_burst = io_input_payload_burst;
  assign io_outputs_1_payload_lock = io_input_payload_lock;
  assign io_outputs_1_payload_cache = io_input_payload_cache;
  assign io_outputs_1_payload_qos = io_input_payload_qos;
  assign io_outputs_1_payload_prot = io_input_payload_prot;
  assign io_outputs_1_fire = (io_outputs_1_valid && io_outputs_1_ready);
  always @(posedge litex_clk or posedge litex_reset) begin
    if(litex_reset) begin
      logic_linkEnable_0 <= 1'b1;
      logic_linkEnable_1 <= 1'b1;
    end else begin
      if(io_outputs_0_fire) begin
        logic_linkEnable_0 <= 1'b0;
      end
      if(io_outputs_1_fire) begin
        logic_linkEnable_1 <= 1'b0;
      end
      if(io_input_ready) begin
        logic_linkEnable_0 <= 1'b1;
        logic_linkEnable_1 <= 1'b1;
      end
    end
  end


endmodule
